-- Seed: Depeche Mode — generated from the JSON data files.
-- Run AFTER migration_core_tables.sql. Idempotent (upserts by id).

on conflict (slug) do update set name = excluded.name, config = excluded.config;

on conflict (id) do update set name=excluded.name, relation=excluded.relation, blurb=excluded.blurb;

on conflict (id) do update set title=excluded.title, category=excluded.category, year=excluded.year, summary=excluded.summary, story=excluded.story, lng=excluded.lng, lat=excluded.lat, approx=excluded.approx, artist_id=excluded.artist_id;

on conflict (id) do update set emoji=excluded.emoji, title=excluded.title, description=excluded.description, badge=excluded.badge, stops=excluded.stops, position=excluded.position;
