insert into public.bands (slug, name, config) values
  ('depeche-mode', 'Depeche Mode', '{"slug":"depeche-mode","name":"Depeche Mode","appTitle":"World in Their Eyes","tagline":"Let me take you on a trip","description":"The definitive fan atlas for Depeche Mode — every studio, stage and story.","coverImage":"/data/bands/depeche-mode/cover.jpg","backgroundImage":"","yearStart":1959,"yearEnd":2026,"defaultMode":"dark","themes":{"dark":{"accent":"#e3342f","accent2":"#8a7bd8","bg":"#0b0b0f","surface":"#15151c","text":"#f2f0eb","mapStyle":"https://api.maptiler.com/maps/dataviz-dark/style.json?key=kbM4ZTal9fF8ZdcNaK8y"},"light":{"accent":"#c2231e","accent2":"#5f4cc0","bg":"#f3f1ea","surface":"#ffffff","text":"#1b1b22","mapStyle":"https://api.maptiler.com/maps/dataviz-light/style.json?key=kbM4ZTal9fF8ZdcNaK8y"}},"map":{"center":[0.4889,51.5762],"zoom":4,"attributionExtra":"Fan-made, non-commercial tribute. Not affiliated with the band."},"categories":{"people":{"label":"The Band","color":"#e964c8","icon":"♥"},"origins":{"label":"Origins","color":"#e3342f","icon":"◆"},"release":{"label":"Releases","color":"#8f96a3","icon":"♪"},"studio":{"label":"Studios","color":"#8a7bd8","icon":"●"},"gig":{"label":"Live","color":"#f5a623","icon":"▲"},"video":{"label":"Videos","color":"#3ec9a7","icon":"■"},"milestone":{"label":"Milestones","color":"#5aa7e8","icon":"★"},"offshoot":{"label":"Offshoots","color":"#9ad14b","icon":"✚"}},"languages":["en","fr","de","es"],"tts":{"model":"eleven_multilingual_v2","voices":{"en":"21m00Tcm4TlvDq8ikWAM","fr":"21m00Tcm4TlvDq8ikWAM","de":"21m00Tcm4TlvDq8ikWAM","es":"21m00Tcm4TlvDq8ikWAM"}},"auth":{"providers":["google","apple"]},"wallIcons":["🌹","🎹","♪","💿","🎤","🎧"],"fanLevels":[{"id":"curious","label":"Curious","blurb":"New here — give me the essentials."},{"id":"fan","label":"Fan","blurb":"I know the hits and the history."},{"id":"devotee","label":"Devotee","blurb":"Hit me with the deep cuts."}],"defaultFanLevel":"fan","gamification":{"checkinLabel":"I made the pilgrimage","contribution":{"label":"Add a memory","points":15,"mediaBonus":10},"tripPoints":30,"contributionBadges":[{"id":"somebody","label":"Somebody","threshold":1},{"id":"see-you","label":"See You","threshold":5},{"id":"memento-mori","label":"Memento Mori","threshold":15}],"streakBadges":[{"id":"balance","label":"Get the Balance Right","days":3},{"id":"question-of-time","label":"A Question of Time","days":7},{"id":"nlmda","label":"Never Let Me Down Again","days":30}],"verified":{"radiusKm":1,"multiplier":3,"badges":[{"id":"walking","label":"Walking in My Shoes","threshold":1},{"id":"stripped","label":"Stripped","threshold":5}]},"badges":[{"id":"first-steps","label":"New Life","threshold":1},{"id":"devotee","label":"Devotee","threshold":5},{"id":"pilgrim","label":"Pilgrim","threshold":12},{"id":"101","label":"101","threshold":25}],"categoryBadges":[{"category":"people","label":"Family Album"},{"category":"origins","label":"Back to Basildon"},{"category":"studio","label":"Studio Rat"},{"category":"gig","label":"Front Row"},{"category":"release","label":"Record Collector"},{"category":"video","label":"Director''s Cut"},{"category":"milestone","label":"History Buff"},{"category":"offshoot","label":"Extended Universe"}],"levels":[{"label":"New Life","points":0},{"label":"Photographic","points":40},{"label":"Everything Counts","points":100},{"label":"Music for the Masses","points":200},{"label":"World in My Eyes","points":350},{"label":"Personal Jesus","points":550}]}}'::jsonb)
insert into public.artists (id, band_slug, name, relation, blurb) values
  ('yazoo', 'depeche-mode', 'Yazoo', 'Vince Clarke offshoot · 1982–83', 'Days after leaving Depeche Mode, Vince Clarke teamed up with Alison Moyet. Two perfect albums — Upstairs at Eric''s and You and Me Both — and singles like Only You and Don''t Go.'),
  ('the-assembly', 'depeche-mode', 'The Assembly', 'Vince Clarke project · 1983', 'Vince Clarke and Blackwing engineer Eric Radcliffe''s one-single project: Never Never, sung by Feargal Sharkey, reached the UK top 5.'),
  ('erasure', 'depeche-mode', 'Erasure', 'Vince Clarke''s band · 1985–present', 'Vince found Andy Bell through a Melody Maker ad and never looked back — 40 years, 19 albums, and some of the greatest pop songs Britain has produced.'),
  ('recoil', 'depeche-mode', 'Recoil', 'Alan Wilder''s project · 1986–present', 'Alan Wilder''s experimental outlet, which became his main vehicle after leaving Depeche Mode in 1995 — cinematic, sample-driven records like Unsound Methods and subHuman.'),
  ('dave-gahan-solo', 'depeche-mode', 'Dave Gahan & Soulsavers', 'Solo · 2003–present', 'Dave''s solo records Paper Monsters and Hourglass proved the voice could write too, and his ongoing collaboration with Soulsavers found gospel-soaked gold.'),
  ('martin-gore-solo', 'depeche-mode', 'Martin L. Gore', 'Solo · 1989–present', 'Martin''s Counterfeit cover EPs and instrumental electronic albums (MG, The Third Chimpanzee) — the songwriter exploring everyone else''s songs, and no songs at all.'),
  ('vcmg', 'depeche-mode', 'VCMG', 'Clarke × Gore collaboration · 2012', 'Thirty years after Vince left, Clarke and Gore reunited for Ssss — a pure techno album made almost entirely by swapping files, barely meeting in person. Very them.')
insert into public.places (id, band_slug, title, category, year, summary, story, lng, lat, approx, artist_id) values
  ('alan-wilder-born', 'depeche-mode', 'Hammersmith, London', 'people', 1959, 'Alan Wilder is born — 1 June 1959.', 'The classically trained musician who joined in 1982 and became the band''s studio architect through their imperial phase, from Construction Time Again to Songs of Faith and Devotion.', -0.2229, 51.4927, false, null),
  ('vince-clarke-born', 'depeche-mode', 'South Woodford, London', 'people', 1960, 'Vince Clarke is born — 3 July 1960.', 'The founding songwriter behind Dreaming of Me, New Life and Just Can''t Get Enough. He left after Speak & Spell to form Yazoo and later Erasure — handing the songwriting torch to Martin Gore.', 0.027, 51.5917, false, null),
  ('martin-gore-born', 'depeche-mode', 'Dagenham, London', 'people', 1961, 'Martin Gore is born — 23 July 1961.', 'Born in Dagenham and raised in Basildon, Martin became the band''s principal songwriter from 1982 onwards — the pen behind Personal Jesus, Enjoy the Silence, Never Let Me Down Again and nearly everything else.', 0.1313, 51.5541, false, null),
  ('andy-fletcher-born', 'depeche-mode', 'Nottingham', 'people', 1961, 'Andy ''Fletch'' Fletcher is born — 8 July 1961.', 'Born in Nottingham before his family moved to Basildon, Fletch was the band''s heart, diplomat and self-described ''tall guy in the background''. He remained a constant for 42 years until his death in May 2022.', -1.1505, 52.9536, false, null),
  ('dave-gahan-born', 'depeche-mode', 'Epping, Essex', 'people', 1962, 'Dave Gahan is born — 9 May 1962.', 'Born in Epping and raised in Basildon, Dave was recruited after Vince Clarke heard him sing Bowie''s ''Heroes'' at a jam session. He even gave the band its name, borrowed from French fashion magazine Dépêche Mode.', 0.11, 51.699, false, null),
  ('basildon', 'depeche-mode', 'Basildon, Essex', 'origins', 1980, 'Where it all began.', 'The Essex new town where Dave Gahan, Martin Gore, Andy Fletcher and Vince Clarke grew up and formed the band in 1980. The town''s pedestrian underpasses and brutalist architecture have become pilgrimage sites for fans from around the world.', 0.4889, 51.5762, false, null),
  ('first-gig', 'depeche-mode', 'St Nicholas School, Basildon', 'gig', 1980, 'The first gig as ''Depeche Mode''.', 'After early shows as Composition of Sound, the freshly renamed Depeche Mode played a school gig in Basildon in the autumn of 1980 — Dave Gahan now on vocals, three synths, and a drum machine. Nobody present knew they were watching history.', 0.4727, 51.5895, true, null),
  ('bridge-house', 'depeche-mode', 'The Bridge House, Canning Town', 'gig', 1980, 'The gig that changed everything.', 'The legendary East London pub venue where the young band played early shows — and where Daniel Miller of Mute Records saw them, leading to the handshake deal that defined their career. The venue closed in 1982; a plaque-worthy spot for any devotee.', 0.0142, 51.5142, false, null),
  ('mute', 'depeche-mode', 'Mute Records, London', 'milestone', 1981, 'The label. The handshake.', 'Daniel Miller''s fiercely independent label signed the band on a handshake and a 50/50 profit split — no contract — and stayed their home for over two decades. One of the great artist-label partnerships in music history.', -0.2199, 51.5273, true, null),
  ('blackwing', 'depeche-mode', 'Blackwing Studios, Southwark', 'studio', 1981, 'The church where synth-pop history was made.', 'Housed in the deconsecrated All Hallows Church in south London, Blackwing is where the first singles and the first two albums took shape — synth-pop history made inside a Victorian church.', -0.1036, 51.4983, false, null),
  ('dreaming-of-me', 'depeche-mode', 'Dreaming of Me — debut single', 'release', 1981, 'The first record, February 1981.', 'Recorded at Blackwing with Daniel Miller producing, the debut single scraped to No. 57 in the UK — enough for Mute to keep going. New Life and Just Can''t Get Enough followed within months, and the rocket left the pad.', -0.1036, 51.4983, false, null),
  ('speak-and-spell', 'depeche-mode', 'Speak & Spell', 'release', 1981, 'The debut album.', 'Recorded at Blackwing and released in October 1981 — bubbly Vince Clarke synth-pop including Just Can''t Get Enough. Weeks after release, Clarke announced he was leaving.', -0.1036, 51.4983, false, null),
  ('totp', 'depeche-mode', 'BBC Television Centre, London', 'milestone', 1981, 'Top of the Pops debut.', 'Performing New Life on Top of the Pops in June 1981 put four Basildon teenagers in front of the whole nation. Fletch kept his bank job a little longer — just in case.', -0.2266, 51.5098, false, null),
  ('first-us-show', 'depeche-mode', 'The Ritz, New York', 'gig', 1982, 'First American show.', 'The band''s first US appearance came at Manhattan''s The Ritz in January 1982 — a teenage synth band a long way from Essex, planting the first seed of what would become one of America''s biggest cult followings.', -73.989, 40.732, true, null),
  ('a-broken-frame', 'depeche-mode', 'A Broken Frame', 'release', 1982, 'Martin takes the pen.', 'Recorded at Blackwing as a trio after Vince Clarke''s departure, with Martin Gore suddenly chief songwriter. See You and Leave in Silence pointed toward the moodier band to come.', -0.1036, 51.4983, false, null),
  ('hammersmith-odeon', 'depeche-mode', 'Hammersmith Odeon, London', 'gig', 1982, 'Alan Wilder''s era begins on stage.', 'Through 1982 the live band was completed by Alan Wilder, recruited via a Melody Maker ad (''must be under 21'' — he wasn''t). London theatre shows like Hammersmith captured the moment the boys became a real touring force.', -0.223, 51.4895, false, null),
  ('construction-time-again', 'depeche-mode', 'Construction Time Again', 'release', 1983, 'Sampling, steel and politics.', 'Recorded at The Garden in Shoreditch (John Foxx''s studio) and mixed at Hansa Berlin. The band discovered sampling — hitting scrap metal for Pipeline — and Everything Counts gave them their anthem of industry and greed.', -0.081, 51.5265, true, null),
  ('hansa', 'depeche-mode', 'Hansa Studios, Berlin', 'studio', 1983, 'The hall by the Wall.', 'The band''s mid-80s creative home, metres from the Berlin Wall. The Meistersaal''s atmosphere — and West Berlin''s nightlife — seeped into the darker, industrial textures of the band''s imperial phase.', 13.3713, 52.5046, false, null),
  ('some-great-reward', 'depeche-mode', 'Some Great Reward', 'release', 1984, 'People are people — and blasphemous rumours.', 'Largely recorded and mixed at Hansa Berlin. People Are People became their first US hit, Master and Servant scandalised radio, and Somebody proved Martin could break hearts with just a piano.', 13.3713, 52.5046, false, null),
  ('black-celebration', 'depeche-mode', 'Black Celebration', 'release', 1986, 'The dark blueprint.', 'Recorded at Westside London and Hansa Berlin, Black Celebration is the moment the band''s gothic, atmospheric identity fully formed — Stripped, A Question of Lust, and a title track for everyone surviving another day.', 13.3713, 52.5046, false, null),
  ('music-for-the-masses', 'depeche-mode', 'Music for the Masses', 'release', 1987, 'The album that conquered America.', 'Recorded largely at Studio Guillaume Tell near Paris with Dave Bascombe. Never Let Me Down Again, Strangelove and Behind the Wheel armed the tour that ended at the Rose Bowl — the ironic title came true.', 2.227, 48.87, true, null),
  ('rose-bowl', 'depeche-mode', 'Rose Bowl, Pasadena', 'gig', 1988, '101 — the concert for the masses.', 'On 18 June 1988, the Music for the Masses tour climaxed in front of roughly 65,000 fans — the band''s 101st and final show of the tour, immortalised in D.A. Pennebaker''s film and live album ''101''. The moment a cult British synth band proved they were a stadium act in America.', -118.1676, 34.1613, false, null),
  ('personal-jesus-video', 'depeche-mode', 'Tabernas Desert, Almería', 'video', 1989, 'Personal Jesus — a western in Spain.', 'Anton Corbijn shot the Personal Jesus video in Spain''s Tabernas Desert, where the spaghetti westerns were filmed — cowboys, horses and a bordello aesthetic for the single that re-invented Depeche Mode with a guitar riff.', -2.39, 37.05, true, null),
  ('puk', 'depeche-mode', 'Puk Studios, Denmark', 'studio', 1989, 'Violator sessions in rural Jutland.', 'A residential studio in the Danish countryside where much of Violator was crafted, with Flood co-producing and Alan Wilder pushing the band''s sound design to new heights.', 10.046, 56.5377, true, null),
  ('violator', 'depeche-mode', 'Violator', 'release', 1990, 'The masterpiece.', 'Begun at Logic Studios in Milan, continued at Puk in Denmark and mixed in London. Personal Jesus, Enjoy the Silence, Policy of Truth, World in My Eyes — the album this very app is named after, and the band''s creative and commercial peak.', 9.19, 45.4642, true, null),
  ('enjoy-the-silence', 'depeche-mode', 'Swiss Alps', 'video', 1990, 'A king with a deckchair.', 'Anton Corbijn filmed Dave Gahan wandering mountain landscapes as a king carrying a deckchair for the Enjoy the Silence video — shot across the Swiss Alps, Portugal and the Scottish Highlands. One of the most iconic music videos ever made.', 8, 46.6, true, null),
  ('tower-records', 'depeche-mode', 'Tower Records, Sunset Strip', 'milestone', 1990, 'The Violator signing ''riot''.', 'A planned in-store signing for Violator in March 1990 drew an estimated 17,000+ fans to West Hollywood, overwhelming police and making the evening news. Proof of just how big the band had become in the US.', -118.385, 34.0905, false, null),
  ('world-violation-giants', 'depeche-mode', 'Giants Stadium, New Jersey', 'gig', 1990, 'World Violation conquers the East Coast.', 'The World Violation Tour sold out Giants Stadium — around 80,000 tickets gone in hours — alongside multiple nights at Dodger Stadium in LA. Violator-era Depeche Mode were, by any measure, one of the biggest bands on Earth.', -74.0776, 40.8128, false, null),
  ('madrid-villa', 'depeche-mode', 'Madrid', 'studio', 1992, 'Songs of Faith and Devotion begins.', 'The band rented a villa in Madrid and converted it into a studio to begin Songs of Faith and Devotion — famously tense sessions, a band fraying at the edges, yet producing some of their most powerful music.', -3.6883, 40.453, true, null),
  ('sofad', 'depeche-mode', 'Songs of Faith and Devotion', 'release', 1993, 'Grunge-era gospel. A UK and US No. 1.', 'Built in the Madrid villa and finished in Hamburg and London, SOFAD debuted at No. 1 on both sides of the Atlantic. I Feel You, Walking in My Shoes, Condemnation — the sound of a band tearing itself apart and making it sing.', -3.6883, 40.453, true, null),
  ('crystal-palace', 'depeche-mode', 'Crystal Palace Bowl, London', 'gig', 1993, 'Devotional comes home.', 'On 31 July 1993, the Devotional Tour played its great London open-air show at Crystal Palace Bowl. The tour was later described as ''the most debauched rock''n''roll tour in history'' — and the music was extraordinary.', -0.07, 51.422, false, null),
  ('exotic-johannesburg', 'depeche-mode', 'Johannesburg, South Africa', 'gig', 1994, 'The Exotic Tour goes where no tour had gone.', 'The 1994 Exotic Tour took the Devotional show to South Africa, South America, Hawaii and Southeast Asia — first-ever shows on several continents, with a band running on fumes. Alan Wilder left the following year.', 28.0473, -26.2041, true, null),
  ('ultra', 'depeche-mode', 'Ultra', 'release', 1997, 'The resurrection record.', 'Recorded with Tim Simenon at Eastcote in London and studios in LA and New York, as a trio and against the odds — Dave newly clean after nearly dying in 1996. Barrel of a Gun and It''s No Good announced the band had survived itself.', -0.205, 51.523, true, null),
  ('singles-tour-tartu', 'depeche-mode', 'Tartu, Estonia', 'gig', 1998, 'The Singles Tour opens behind the old Iron Curtain.', 'The Singles Tour 86>98 opened in Tartu, Estonia in September 1998 — a nod to the band''s enormous Eastern European following, where bootleg tapes had made them folk heroes long before they could play there.', 26.729, 58.3776, true, null),
  ('exciter', 'depeche-mode', 'Exciter', 'release', 2001, 'Minimal, digital, tender.', 'Produced by LFO''s Mark Bell, with sessions at RAK in London and studios in Santa Barbara and New York. Dream On and I Feel Loved took the band into the new century with a quieter kind of confidence.', -0.172, 51.533, true, null),
  ('sound-design', 'depeche-mode', 'Santa Barbara, California', 'studio', 2005, 'The band''s West Coast home base.', 'From the mid-2000s, much of every album took shape in Santa Barbara, where Martin Gore settled — at Sound Design and later his home studio, wonderfully named Electric Ladyboy. The Essex boys'' story now runs through Californian sunshine.', -119.6982, 34.4208, true, null),
  ('playing-the-angel', 'depeche-mode', 'Playing the Angel', 'release', 2005, 'Pain and suffering in various tempos.', 'Recorded in Santa Barbara and New York with Ben Hillier. Precious returned them to the top 10 worldwide, and for the first time Dave Gahan contributed songs — including Suffer Well.', -119.6982, 34.4208, true, null),
  ('touring-the-angel-milan', 'depeche-mode', 'Forum di Assago, Milan', 'gig', 2006, 'Touring the Angel: Live in Milan.', 'The Touring the Angel shows at Milan''s Forum were filmed for the celebrated live DVD — Italy''s famously devoted fanbase providing one of the loudest crowds the band ever recorded.', 9.1428, 45.402, false, null),
  ('sounds-of-the-universe', 'depeche-mode', 'Sounds of the Universe', 'release', 2009, 'Vintage synths from eBay.', 'Martin bought a trove of vintage analogue gear online and the band built the album around it in Santa Barbara and New York. Wrong gave them one of their strangest, darkest singles — and videos.', -119.6982, 34.4208, true, null),
  ('tour-universe-tel-aviv', 'depeche-mode', 'Ramat Gan Stadium, Tel Aviv', 'gig', 2009, 'Tour of the Universe lifts off.', 'The Tour of the Universe opened in Tel Aviv in May 2009. Days later Dave was diagnosed with a bladder tumour, forcing postponements — he recovered, and the tour went on to play to over 2.7 million people.', 34.824, 32.078, false, null),
  ('tour-universe-barcelona', 'depeche-mode', 'Palau Sant Jordi, Barcelona', 'gig', 2009, 'Tour of the Universe: Barcelona — the live film.', 'The November 2009 Barcelona shows were filmed for the Tour of the Universe live album and film — Spain''s fervent fanbase captured in full voice for posterity.', 2.1174, 41.3641, false, null),
  ('delta-machine', 'depeche-mode', 'Delta Machine', 'release', 2013, 'Blues in the machine.', 'Recorded in Santa Barbara and at Jungle City in New York with Ben Hillier. Heaven and Should Be Higher leaned into the gospel-blues undercurrent that had always run beneath the synths.', -74.002, 40.751, true, null),
  ('delta-stade-de-france', 'depeche-mode', 'Stade de France, Paris', 'gig', 2013, 'The Delta Machine Tour at full scale.', 'The 2013–14 Delta Machine Tour filled Europe''s biggest stadiums, including the Stade de France — three decades on from Blackwing, still growing.', 2.3601, 48.9245, false, null),
  ('spirit', 'depeche-mode', 'Spirit', 'release', 2017, 'Where''s the revolution?', 'Recorded in Santa Barbara and New York with James Ford producing — the band''s angriest, most political record since the 80s, released into a world that had caught up with its warnings.', -119.6982, 34.4208, true, null),
  ('global-spirit-stockholm', 'depeche-mode', 'Friends Arena, Stockholm', 'gig', 2017, 'Global Spirit Tour opens.', 'The Global Spirit Tour opened in Stockholm in May 2017 and went on to reach more than 3 million people — at the time one of the highest-attended tours in the world.', 17.929, 59.3725, false, null),
  ('waldbuehne', 'depeche-mode', 'Waldbühne, Berlin', 'gig', 2018, 'A spiritual home crowd.', 'The Global Spirit tour closed with celebrated 2018 Waldbühne shows in Berlin — the city that shaped the band''s sound — filmed for the SPiRiTS in the Forest documentary, a love letter to the fans themselves.', 13.2406, 52.5158, false, null),
  ('rock-hall', 'depeche-mode', 'Rock & Roll Hall of Fame, Cleveland', 'milestone', 2020, 'Inducted at last.', 'In 2020, Depeche Mode were inducted into the Rock & Roll Hall of Fame — formal recognition, four decades in, that the synthesizer band from Basildon changed popular music.', -81.6954, 41.5085, false, null),
  ('memento-mori', 'depeche-mode', 'Memento Mori', 'release', 2023, 'Remember you must die — so live.', 'Largely written before Andy Fletcher''s death in May 2022 and recorded in Santa Barbara and New York with James Ford. Ghosts Again gave the band their most beloved single in years; the album is dedicated to Fletch''s memory.', -119.6982, 34.4208, true, null),
  ('memento-mori-opener', 'depeche-mode', 'Golden 1 Center, Sacramento', 'gig', 2023, 'Memento Mori begins.', 'On 23 March 2023, Dave and Martin opened the Memento Mori world tour — the first without Andy Fletcher, whose memory the tour honoured nightly. It became one of the highest-grossing tours of the band''s career.', -121.4996, 38.5802, false, null),
  ('memento-mori-twickenham', 'depeche-mode', 'Twickenham Stadium, London', 'gig', 2023, 'Memento Mori''s London homecoming.', 'In June 2023 the Memento Mori tour came home to London''s 80,000-capacity Twickenham Stadium — Basildon boys, 43 years on, still filling the biggest stages in their own country.', -0.3415, 51.4559, false, null),
  ('memento-mori-finale', 'depeche-mode', 'Bilbao, Spain', 'gig', 2024, 'The final show of Memento Mori.', 'The Memento Mori world tour closed in Bilbao in April 2024 after 112 shows across the globe — the end of the band''s most emotional tour, and (for now) the latest chapter of the story.', -2.992, 43.289, true, null),
  ('yazoo-upstairs', 'depeche-mode', 'Yazoo — Upstairs at Eric''s', 'offshoot', 1982, 'Vince''s next chapter, same studio.', 'Within weeks of leaving Depeche Mode, Vince Clarke was back at Blackwing with Alison Moyet recording Yazoo''s debut — named after engineer Eric Radcliffe''s upstairs room. Only You and Don''t Go came out of the very building where Speak & Spell was made.', -0.1036, 51.4983, false, 'yazoo'),
  ('the-assembly-never-never', 'depeche-mode', 'The Assembly — Never Never', 'offshoot', 1983, 'Vince and Eric''s top-5 one-off.', 'Vince Clarke and Blackwing''s Eric Radcliffe planned a project with a different singer on every release. They managed one: Never Never with Feargal Sharkey, a UK No. 4 — then Vince met Andy Bell and Erasure happened instead.', -0.1036, 51.4983, false, 'the-assembly'),
  ('erasure-formed', 'depeche-mode', 'Erasure forms in London', 'offshoot', 1985, 'Audition number 42: Andy Bell.', 'Vince Clarke auditioned singers through a Melody Maker ad; Andy Bell was the 42nd hopeful. Wonderland followed in 1986, and Erasure became one of Britain''s most enduring pop acts — still going four decades later.', -0.1276, 51.5072, true, 'erasure'),
  ('recoil-thin-line', 'depeche-mode', 'Recoil — The Thin Line, Sussex', 'offshoot', 1995, 'Alan Wilder''s life after Mode.', 'After leaving Depeche Mode in 1995, Alan Wilder made Recoil his full-time vehicle, recording dark, cinematic albums like Unsound Methods and subHuman at his Sussex home studio, The Thin Line.', 0.05, 50.95, true, 'recoil'),
  ('counterfeit2', 'depeche-mode', 'Martin L. Gore — Counterfeit²', 'offshoot', 2003, 'The songwriter sings everyone else.', 'Martin''s solo outlet has always been covers and instrumentals — the Counterfeit EPs and later the MG and Third Chimpanzee albums, made at his Santa Barbara home studio. The writer of hundreds of songs, relaxing in other people''s.', -119.6982, 34.4208, true, 'martin-gore-solo'),
  ('paper-monsters', 'depeche-mode', 'Dave Gahan — Paper Monsters', 'offshoot', 2003, 'The voice becomes a writer.', 'Dave''s solo debut, written and recorded in New York where he''d rebuilt his life. Its success changed Depeche Mode itself — from Playing the Angel onwards, Gahan songs appear on every album.', -73.99, 40.73, true, 'dave-gahan-solo'),
  ('soulsavers', 'depeche-mode', 'Dave Gahan & Soulsavers', 'offshoot', 2012, 'Gospel, soul and redemption songs.', 'Dave''s ongoing collaboration with production duo Soulsavers — The Light the Dead See, Angels & Ghosts and Imposter — recorded largely in Los Angeles, gave his voice its most soulful setting outside the Mode.', -118.25, 34.05, true, 'dave-gahan-solo'),
  ('crocs-rayleigh', 'depeche-mode', 'Croc''s, Rayleigh', 'gig', 1980, 'The Essex residency.', 'The crocodile-themed Rayleigh club (later the Pink Toothbrush) where the fledgling band played a near-weekly residency in 1980–81, building the local following that carried them to London.', 0.6049, 51.5864, true, null),
  ('vince-leaves', 'depeche-mode', 'Vince Clarke leaves', 'milestone', 1981, 'The songwriter walks, weeks after the debut.', 'In November 1981, with Speak & Spell still climbing the charts, Vince Clarke announced he was leaving. Most bands would have died on the spot; instead, 20-year-old Martin Gore picked up the pen.', 0.4889, 51.5762, false, null),
  ('just-cant-get-enough', 'depeche-mode', 'Just Can''t Get Enough — single', 'release', 1981, 'The evergreen.', 'Recorded at Blackwing and released in September 1981, Vince Clarke''s bubblegum masterpiece became the band''s first top-10 hit — and forty years on, a football-terrace anthem sung by people who couldn''t name the band.', -0.1036, 51.4983, false, null),
  ('alan-joins', 'depeche-mode', 'Alan Wilder joins', 'milestone', 1982, '''Must be under 21.'' He lied.', 'Answering a Melody Maker ad seeking a synth player (under 21 only — Alan was 22), the classically trained Wilder auditioned in London and got the gig. He became the sonic architect of the band''s greatest records.', -0.1036, 51.4983, true, null),
  ('us-festival', 'depeche-mode', 'US Festival, San Bernardino', 'gig', 1983, 'Playing to a sea of confused Californians.', 'On ''New Wave Day'' at the 1983 US Festival, the young band played to one of the biggest crowds of their life in the California desert — an early, surreal taste of the American scale to come.', -117.3956, 34.1764, true, null),
  ('people-are-people-video', 'depeche-mode', 'HMS Belfast, London', 'video', 1984, 'People Are People — filmed on a warship.', 'The video for the band''s first US hit was shot aboard HMS Belfast on the Thames, its industrial clanks and naval guns matching the track''s metal-bashing samples.', -0.0813, 51.5066, false, null),
  ('live-in-hamburg', 'depeche-mode', 'Alsterdorfer Sporthalle, Hamburg', 'gig', 1984, 'The World We Live In and Live in Hamburg.', 'The Some Great Reward tour''s Hamburg stop was filmed for the band''s first concert video — early proof of the German devotion that would define their career.', 9.9899, 53.6126, false, null),
  ('first-japan', 'depeche-mode', 'Tokyo, Japan', 'gig', 1985, 'First shows in Japan.', 'The band''s first Japanese dates in April 1985 opened up yet another devoted territory — the start of a relationship with Japan that continues to this day.', 139.6638, 35.7089, true, null),
  ('personal-jesus-single', 'depeche-mode', 'Personal Jesus — single', 'release', 1989, 'Reach out and touch faith.', 'Built around a blues guitar riff at Logic Studios in Milan and teased via newspaper ads reading ''Your own personal Jesus'' with a phone number, it became one of the most covered songs in the catalogue — Johnny Cash and Marilyn Manson included.', 9.19, 45.4642, true, null),
  ('enjoy-the-silence-single', 'depeche-mode', 'Enjoy the Silence — single', 'release', 1990, 'The masterpiece''s masterpiece.', 'Martin wrote it as a slow ballad; Alan Wilder and Flood heard a dance track at Puk Studios and rebuilt it overnight. The result won the 1991 BRIT for Best Single and remains the band''s defining song.', 10.046, 56.5377, true, null),
  ('enjoy-the-silence-highlands', 'depeche-mode', 'Scottish Highlands', 'video', 1990, 'The king walks Scotland.', 'The Scottish leg of Anton Corbijn''s Enjoy the Silence shoot — Dave''s wandering king crossing the Highlands with his deckchair, a long way from his kingdom.', -4.5, 57.1, true, null),
  ('dodger-stadium', 'depeche-mode', 'Dodger Stadium, Los Angeles', 'gig', 1990, 'World Violation owns LA.', 'Two sold-out nights at Dodger Stadium in August 1990 — around 90,000 tickets — confirmed Los Angeles as the band''s American heartland, two years after the Rose Bowl.', -118.2399, 34.0739, false, null),
  ('msg', 'depeche-mode', 'Madison Square Garden, New York', 'gig', 1990, 'A New York institution, era after era.', 'From World Violation in 1990 through Tour of the Universe and Memento Mori, the Garden became the band''s New York home — a venue they''ve filled across five decades.', -73.9934, 40.7505, false, null),
  ('devotional-lievin', 'depeche-mode', 'Stade Couvert, Liévin', 'gig', 1993, 'The Devotional film.', 'Anton Corbijn filmed the Devotional concert film at the band''s December 1993 shows in this northern French arena — the band at their darkest, heaviest and, many fans argue, their absolute live peak.', 2.7706, 50.4221, false, null),
  ('hollywood-rock-rio', 'depeche-mode', 'Rio de Janeiro, Brazil', 'gig', 1994, 'The Exotic Tour reaches South America.', 'January 1994 festival shows in Brazil brought the Devotional set to South America for the first time — another continent claimed by the Exotic Tour''s exhausted, brilliant band.', -43.1965, -22.9132, true, null),
  ('alan-leaves', 'depeche-mode', 'Alan Wilder leaves', 'milestone', 1995, 'The architect departs.', 'In June 1995, after the punishing Devotional era, Alan Wilder announced his departure, citing years of unequal workload. The band continued as a trio; he returned just once — joining Martin for Somebody at Royal Albert Hall in 2010.', -0.118, 51.508, true, null),
  ('ultra-party', 'depeche-mode', 'Adrenalin Village, London', 'milestone', 1997, 'Ultra launches. The band survives.', 'With no tour possible after Dave''s recovery, Ultra launched with two ''Ultra Parties'' — London and Los Angeles. Short sets, huge relief: Depeche Mode still existed.', -0.1485, 51.4828, true, null),
  ('barrel-of-a-gun-video', 'depeche-mode', 'Morocco', 'video', 1997, 'Barrel of a Gun — Corbijn in North Africa.', 'Anton Corbijn shot the fevered, eye-painted Barrel of a Gun video in Morocco — the dark, disorientating image of the band''s resurrection record.', -7.98, 31.63, true, null),
  ('one-night-in-paris', 'depeche-mode', 'Palais Omnisports de Paris-Bercy', 'gig', 2001, 'One Night in Paris.', 'The Exciter Tour''s Paris stop was filmed by Anton Corbijn as ''One Night in Paris'' — elegant, stripped back, and proof the band had grown into their third decade with style intact.', 2.3786, 48.8384, false, null),
  ('wrong-video', 'depeche-mode', 'Downtown Los Angeles', 'video', 2009, 'Wrong — the backwards car ride.', 'A masked man strapped in a car rolling backwards through downtown LA at dawn — the unsettling, award-nominated Wrong video became one of the band''s most talked-about late-era moments.', -118.2437, 34.0522, true, null),
  ('heaven-video', 'depeche-mode', 'Marigny Opera House, New Orleans', 'video', 2013, 'Heaven — filmed in a ruined church.', 'Timothy Saccenti shot the Heaven video in the candle-lit, deconsecrated Marigny Opera House — gospel atmosphere for Delta Machine''s lead single, in the city that invented the mood.', -90.0578, 29.9647, false, null),
  ('live-in-berlin', 'depeche-mode', 'O2 World, Berlin', 'gig', 2013, 'Live in Berlin.', 'Anton Corbijn filmed the Delta Machine tour''s Berlin nights for the ''Live in Berlin'' film and album — the band returning, as always, to the city that shaped them.', 13.4539, 52.5054, false, null),
  ('foro-sol', 'depeche-mode', 'Foro Sol, Mexico City', 'gig', 2013, 'Mexican devotion.', 'Mexico City''s enormous Foro Sol shows — tens of thousands singing every word — cemented Mexico as one of the band''s most passionate territories, revisited on every tour since.', -99.0976, 19.4042, true, null),
  ('fletch-farewell', 'depeche-mode', 'Remembering Fletch', 'milestone', 2022, 'Andy Fletcher, 1961–2022.', 'Andy Fletcher died at home in London in May 2022, aged 60. The band''s heart and quiet diplomat for 42 years, he was honoured nightly on the Memento Mori tour — ''Fletch would have loved this song.''', -0.1276, 51.5072, true, null),
  ('ghosts-again-single', 'depeche-mode', 'Ghosts Again — single', 'release', 2023, 'Heaven''s dreaming, ghosts again.', 'Written with Richard Butler of the Psychedelic Furs and recorded in Santa Barbara, Ghosts Again gave the two-piece Depeche Mode their most beloved single in a decade — melancholy, danceable, defiantly alive.', -119.6982, 34.4208, true, null),
  ('ghosts-again-video', 'depeche-mode', 'New York rooftops', 'video', 2023, 'Ghosts Again — chess with death, gently.', 'Anton Corbijn filmed Dave and Martin playing rooftop chess in New York — a tender Seventh Seal nod for a song about mortality, made by two men who had just lost their oldest friend.', -73.99, 40.735, true, null),
  ('vcmg-ssss', 'depeche-mode', 'VCMG — Ssss', 'offshoot', 2012, 'Clarke × Gore, reunited by email.', 'Thirty years after Vince walked out, Clarke and Gore made a full-on techno album together for Mute — almost entirely by swapping files, barely in the same room. The most Depeche Mode reunion imaginable.', -0.2199, 51.5273, true, 'vcmg'),
  ('logic-milan', 'depeche-mode', 'Logic Studios, Milan', 'studio', 1989, 'Where Violator was born.', 'Early in 1989 the band decamped to Milan''s Logic Studios to begin Violator with producer Flood. Personal Jesus took shape here before the sessions moved north to Puk in Denmark — the first sparks of their masterpiece.', 9.19, 45.4642, true, null),
  ('westside-london', 'depeche-mode', 'Westside Studios, London', 'studio', 1986, 'Building Black Celebration.', 'Much of Black Celebration was tracked at Westside in west London before mixing at Hansa. The album where Depeche Mode fully embraced the dark — Stripped, A Question of Time, and the title-track dread that defined a generation of fans.', -0.2089, 51.5101, true, null),
  ('wembley-arena', 'depeche-mode', 'Wembley Arena, London', 'gig', 1988, 'The London homecoming room.', 'Across the Music for the Masses, World Violation and Devotional tours, Wembley Arena was the band''s London stronghold — sweaty, ecstatic nights that turned a generation of British kids into lifelong devotees.', -0.2825, 51.5582, false, null),
  ('pinkpop', 'depeche-mode', 'Pinkpop Festival, Netherlands', 'gig', 1984, 'Mainland Europe falls hard.', 'A blazing 1984 Pinkpop set in Landgraaf helped cement the Low Countries as Depeche Mode heartland — a devotion that has never cooled across four decades of return visits.', 5.9989, 50.8932, true, null),
  ('torhout-werchter', 'depeche-mode', 'Rock Werchter, Belgium', 'gig', 1984, 'Festival fields of Flanders.', 'The twin Torhout–Werchter festival in the summer of 1984 put the young band in front of vast Belgian crowds — another European territory won by sheer relentless touring.', 4.66, 50.9886, true, null),
  ('buenos-aires-exotic', 'depeche-mode', 'Buenos Aires, Argentina', 'gig', 1994, 'The Exotic Tour hits South America.', 'On the punishing 1994 Exotic Tour, Depeche Mode reached Argentina for the first time — a continent of new devotees discovered just as the band was burning itself to the ground. The fans never forgot.', -58.3816, -34.6037, true, null),
  ('world-in-my-eyes', 'depeche-mode', 'World in My Eyes — single', 'release', 1990, 'Let me take you on a trip.', 'The final single from Violator, recorded at Puk in Denmark — Martin Gore''s hymn to intimacy and travel. "Let me take you on a trip": the song that gives this atlas its name and its spirit.', 10.046, 56.5377, true, null),
  ('strangelove-video', 'depeche-mode', 'Strangelove video, Paris', 'video', 1987, 'Corbijn''s first DM video.', 'Anton Corbijn shot Strangelove in moody monochrome Paris — the beginning of a creative partnership that would shape the band''s entire visual identity for the next forty years.', 2.3412, 48.8698, true, null),
  ('its-no-good-video', 'depeche-mode', 'It''s No Good video, Las Vegas', 'video', 1997, 'Dave as the lounge act from hell.', 'Corbijn cast Dave Gahan as a washed-up Vegas crooner playing to empty tables — gloriously self-aware comedy from a band that had just stared down the abyss and lived to laugh about it.', -115.1728, 36.1147, true, null)
insert into public.trips (id, band_slug, emoji, title, description, badge, stops, position) values
  ('basildon-story', 'depeche-mode', '🏘️', 'From Basildon, With Synths', 'Five births, one new town, and the gigs that lit the fuse — the origin story, 1959–1981.', 'Composition of Sound', '["alan-wilder-born","vince-clarke-born","martin-gore-born","andy-fletcher-born","dave-gahan-born","basildon","first-gig","crocs-rayleigh","bridge-house","totp"]'::jsonb, 0),
  ('albums-in-order', 'depeche-mode', '💿', 'Every Album, In Order', 'All fifteen studio albums, from a south London church to the Californian coast.', 'Black Swarm', '["speak-and-spell","a-broken-frame","construction-time-again","some-great-reward","black-celebration","music-for-the-masses","violator","sofad","ultra","exciter","playing-the-angel","sounds-of-the-universe","delta-machine","spirit","memento-mori"]'::jsonb, 1),
  ('conquering-america', 'depeche-mode', '🇺🇸', 'Conquering America', 'From a Manhattan club in ''82 to the Rose Bowl, a record-store riot and the Hall of Fame.', 'Concert for the Masses', '["first-us-show","us-festival","rose-bowl","tower-records","dodger-stadium","world-violation-giants","msg","rock-hall"]'::jsonb, 2),
  ('violator', 'depeche-mode', '🌹', 'Violator: The Masterpiece', 'From a Milan studio to a Sunset Strip riot — the making of the album that conquered the world.', 'Enjoy the Silence', '["logic-milan","puk","violator","personal-jesus-single","personal-jesus-video","enjoy-the-silence-single","enjoy-the-silence","world-in-my-eyes","tower-records","world-violation-giants"]'::jsonb, 3),
  ('berlin-years', 'depeche-mode', '🧱', 'The Berlin Years', 'The hall by the Wall and the city that turned synth-pop dark.', 'Hall by the Wall', '["hansa","some-great-reward","black-celebration","live-in-berlin","waldbuehne"]'::jsonb, 4),
  ('corbijn-lens', 'depeche-mode', '🎥', 'Through Corbijn''s Lens', 'Deserts, mountains, warships and rooftops — the image-maker''s greatest locations.', 'The Image Maker', '["strangelove-video","people-are-people-video","personal-jesus-video","enjoy-the-silence","enjoy-the-silence-highlands","devotional-lievin","barrel-of-a-gun-video","its-no-good-video","one-night-in-paris","wrong-video","ghosts-again-video"]'::jsonb, 5),
  ('daves-journey', 'depeche-mode', '🎤', 'Dave''s Journey', 'From Epping to the Rose Bowl, through the abyss and out the other side.', 'The Voice', '["dave-gahan-born","totp","rose-bowl","ultra","paper-monsters","soulsavers","memento-mori-opener"]'::jsonb, 6),
  ('vinces-path', 'depeche-mode', '🎛️', 'The Vince Clarke Multiverse', 'Wrote the first hits, left after one album, and never stopped — Yazoo, Erasure, VCMG.', 'Upstairs at Eric''s', '["vince-clarke-born","speak-and-spell","vince-leaves","yazoo-upstairs","the-assembly-never-never","erasure-formed","vcmg-ssss"]'::jsonb, 7),
  ('memento-mori-tour', 'depeche-mode', '🕊️', 'Memento Mori', 'Losing Fletch, and the tour that turned grief into one last triumph.', 'Ghosts Again', '["fletch-farewell","memento-mori","memento-mori-opener","memento-mori-twickenham","memento-mori-finale"]'::jsonb, 8)
